/**
 * Deterministic content-subtitle generation. Produces a short, accurate
 * descriptive subtitle from a content type + the fields already present in
 * that type's content schema — generated by the worker, stored on
 * PublishedContent.subtitle, and rendered under the title. Pure +
 * deterministic: no AI, no network, no fields outside the schemas.
 *
 * Examples:
 *   Saint Peter           -> "Apostle, patron of the papacy · Feast June 29"
 *   Pope St John Paul II  -> "Pope from 1978 to 2005"
 *   St Thomas Aquinas     -> "Religious · Doctor of the Church — Angelic Doctor · Feast January 28"
 *   Lourdes               -> "Church-approved Marian apparition · Lourdes, France, 1858"
 *   Rerum Novarum         -> "Encyclical of Pope Leo XIII (1891)"
 *   Christmas             -> "Solemnity · December 25 · Christmas season"
 *   St Peter's Basilica   -> "Major basilica · Vatican City, Vatican City State · Diocese of Rome"
 */

export interface SubtitleInput {
  contentType: string;
  contentSubtype?: string | null;
  title?: string | null;
  fields?: Record<string, unknown>;
}

type Fields = Record<string, unknown>;

function str(v: unknown): string {
  return typeof v === "string" ? v.trim() : "";
}

function num(v: unknown): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string" && /^\d+$/.test(v.trim())) return parseInt(v, 10);
  return null;
}

function arr(v: unknown): unknown[] {
  return Array.isArray(v) ? v : [];
}

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

/** "06-29" -> "June 29"; anything else is returned trimmed as-is. */
export function formatFeastDate(value: unknown): string {
  const s = str(value);
  const m = /^(\d{2})-(\d{2})$/.exec(s);
  if (!m) return s;
  const month = MONTHS[parseInt(m[1], 10) - 1];
  const day = parseInt(m[2], 10);
  if (!month || !day) return s;
  return `${month} ${day}`;
}

/** "1891-05-15" -> "1891"; "0325-01-01" -> "325"; "1978" -> "1978". */
function yearOf(value: unknown): string {
  const s = str(value);
  const m = /^(\d{1,4})(?:-\d{2}-\d{2})?$/.exec(s);
  if (!m) return "";
  return String(parseInt(m[1], 10));
}

/** "saint-faustina-kowalska" -> "Saint Faustina Kowalska". */
function humanizeSlug(slug: string): string {
  return slug
    .split("-")
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function ordinal(n: number): string {
  const mod100 = n % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${n}th`;
  switch (n % 10) {
    case 1:
      return `${n}st`;
    case 2:
      return `${n}nd`;
    case 3:
      return `${n}rd`;
    default:
      return `${n}th`;
  }
}

// ---------------------------------------------------------------------------
// SAINT
// ---------------------------------------------------------------------------

const SAINT_TYPE_LABELS: Record<string, string> = {
  apostle: "Apostle",
  evangelist: "Evangelist",
  martyr: "Martyr",
  doctor_of_the_church: "Doctor of the Church",
  virgin: "Virgin",
  bishop: "Bishop",
  pope: "Pope",
  founder: "Religious founder",
  missionary: "Missionary",
  religious: "Religious",
  lay: "Lay faithful",
  confessor: "Confessor",
  other: "Saint",
};

const CANONIZATION_PREFIX: Record<string, string> = {
  beatified: "Blessed",
  venerable: "Venerable",
  servant_of_god: "Servant of God",
};

function saintSubtitle(f: Fields): string {
  const typeLabel = SAINT_TYPE_LABELS[str(f.saintType)];
  const prefix = CANONIZATION_PREFIX[str(f.canonizationStatus)] ?? "";
  const patron = str(arr(f.patronages)[0]);
  const feast = formatFeastDate(f.feastDay);
  if (!typeLabel && !patron && !feast) {
    // Legacy payloads (role / patronage) and the bare fallback.
    const legacy = str(f.role) || str(f.patronage);
    return legacy ? `Saint — ${legacy}` : "A saint of the Catholic Church";
  }
  const head = `${prefix ? `${prefix} · ` : ""}${typeLabel ?? "Saint"}`;
  return `${head}${patron ? `, patron of ${patron}` : ""}${feast ? ` · Feast ${feast}` : ""}`;
}

// ---------------------------------------------------------------------------
// POPE
// ---------------------------------------------------------------------------

function popeSubtitle(f: Fields): string {
  const start = str(f.papacyStart);
  const rawEnd = str(f.papacyEnd);
  const end = rawEnd && rawEnd.toLowerCase() !== "present" ? rawEnd : "";
  const ord = num(f.ordinal);
  if (!start) return "Pope, Bishop of Rome";
  if (ord != null) return `${ordinal(ord)} Pope · ${start}–${end || "present"}`;
  return end ? `Pope from ${start} to ${end}` : `Pope since ${start}`;
}

// ---------------------------------------------------------------------------
// DOCTOR
// ---------------------------------------------------------------------------

const ECCLESIAL_ROLE_LABELS: Record<string, string> = {
  pope: "Pope",
  bishop: "Bishop",
  priest: "Priest",
  deacon: "Deacon",
  religious: "Religious",
  lay: "Lay faithful",
};

function doctorSubtitle(f: Fields): string {
  const epithet = str(f.doctorTitle);
  const role = ECCLESIAL_ROLE_LABELS[str(f.ecclesialRole)] ?? "";
  const feast = formatFeastDate(f.feastDay);
  const core =
    epithet && epithet.toLowerCase() !== "doctor of the church"
      ? `Doctor of the Church — ${epithet}`
      : "Doctor of the Church";
  return `${role ? `${role} · ` : ""}${core}${feast ? ` · Feast ${feast}` : ""}`;
}

// ---------------------------------------------------------------------------
// APPARITION
// ---------------------------------------------------------------------------

function apparitionStatusLabel(status: string, subjectWord: string): string {
  switch (status) {
    case "approved":
    case "constat_de_supernaturalitate":
      return `Church-approved ${subjectWord}`;
    case "nihil_obstat":
      return `${subjectWord.charAt(0).toUpperCase()}${subjectWord.slice(1)} granted nihil obstat`;
    case "under_investigation":
    case "not_yet_judged":
    case "prae_oculis_habeatur":
    case "curatur":
    case "sub_mandato":
      return `${subjectWord.charAt(0).toUpperCase()}${subjectWord.slice(1)} under Church review`;
    case "non_constat":
      return `${subjectWord.charAt(0).toUpperCase()}${subjectWord.slice(1)} not confirmed by the Church`;
    case "not_supernatural":
    case "declaratio_de_non_supernaturalitate":
      return "Reported apparition judged not supernatural";
    case "prohibetur_et_obstruatur":
      return "Reported apparition not permitted by the Church";
    case "private_revelation":
      return "Private revelation";
    default:
      return "";
  }
}

function apparitionSubtitle(f: Fields): string {
  const subject = str(f.subject);
  const subjectWord =
    subject === "christ"
      ? "apparition of Christ"
      : subject === "saint"
        ? "apparition of a saint"
        : subject === "angel"
          ? "apparition of an angel"
          : "Marian apparition";
  const schemaStatus = str(f.approvedStatus).toLowerCase();
  let label = apparitionStatusLabel(schemaStatus, subjectWord);
  if (!label) {
    // Legacy field names (approvalStatus / status) carry free text.
    const legacy = str(f.approvalStatus ?? f.status).toLowerCase();
    if (legacy.includes("approv")) label = `Church-approved ${subjectWord}`;
    else if (legacy.includes("condemn"))
      label = `${subjectWord.charAt(0).toUpperCase()}${subjectWord.slice(1)} not approved by the Church`;
    else if (legacy.includes("review"))
      label = `${subjectWord.charAt(0).toUpperCase()}${subjectWord.slice(1)} under Church review`;
    else label = `Reported ${subjectWord}`;
  }
  const where = [str(f.location), str(f.country)].filter(Boolean);
  const year = num(f.yearOfApparition);
  const tail = [...where, year != null ? String(year) : ""].filter(Boolean).join(", ");
  return tail ? `${label} · ${tail}` : label;
}

// ---------------------------------------------------------------------------
// MARIAN_TITLE
// ---------------------------------------------------------------------------

/** The four Marian dogmas, keyed by curated slug, with the year each was defined. */
export const MARIAN_DOGMA_YEARS: Readonly<Record<string, number>> = {
  "mother-of-god": 431,
  "immaculate-conception": 1854,
  "assumption-of-mary": 1950,
  "perpetual-virginity": 649,
};

function marianTitleSubtitle(f: Fields): string {
  const slug = str(f.slug);
  const dogmaYear = num(f.dogmaDefinedYear) ?? MARIAN_DOGMA_YEARS[slug] ?? null;
  if (dogmaYear != null) return `Marian dogma · defined ${dogmaYear}`;
  const feast = formatFeastDate(f.feastDay);
  const region = str(f.region);
  return `Title of the Blessed Virgin Mary${feast ? ` · Feast ${feast}` : ""}${region ? ` · ${region}` : ""}`;
}

