function sacramentSubtitle(f: Fields): string {
  return SACRAMENT_GROUP[str(f.sacramentKey)] ?? "One of the seven sacraments of the Church";
}

// ---------------------------------------------------------------------------
// PRAYER / LITANY
// ---------------------------------------------------------------------------

function prayerSubtypeSubtitle(subtype: string | null): string {
  switch (subtype) {
    case "marian_prayer":
      return "A Marian prayer of the Catholic Church";
    case "eucharistic_prayer":
      return "A Eucharistic prayer of the Catholic Church";
    case "saint_prayer":
      return "A prayer to a saint of the Church";
    case "liturgical_prayer":
      return "A prayer of the sacred liturgy";
    case "litany_invocation":
    case "full_litany":
      return "A litany of the Catholic Church";
    default:
      return "A prayer of the Catholic Church";
  }
}

const PRAYER_TYPE_LABELS: Record<string, string> = {
  morning: "Morning prayer",
  evening: "Evening prayer",
  meal: "Grace before/after meals",
  litany: "Litany — invocations and responses",
  novena: "Novena prayer",
  rosary: "Rosary prayer",
  marian: "Marian prayer",
  intercession: "Prayer of intercession",
  consecration: "Act of consecration",
  chaplet: "Chaplet prayer",
  psalm: "Psalm",
  canticle: "Canticle",
  hymn: "Hymn of the Church",
  general: "Catholic prayer",
};

function prayerSubtitle(f: Fields, subtype: string | null, title: string): string {
  const type = str(f.prayerType);
  let label: string;
  if (type === "act") {
    const m = /^act of (.+)$/i.exec(title.trim());
    label = m ? `Act of ${m[1].trim().toLowerCase()}` : "Act of devotion";
  } else {
    label = PRAYER_TYPE_LABELS[type] ?? "";
  }
  if (!label) return prayerSubtypeSubtitle(subtype);
  const translations = arr(f.translations).length;
  return `${label}${str(f.latin) ? " · Latin text" : ""}${translations > 0 ? ` · ${translations} translations` : ""}`;
}

// ---------------------------------------------------------------------------
// NOVENA
// ---------------------------------------------------------------------------

function novenaSubtitle(f: Fields): string {
  const duration = num(f.durationDays);
  const days = arr(f.days).length;
  const head =
    duration != null && duration !== 9
      ? `${duration}-day novena`
      : days > 9
        ? `${days}-day novena`
        : "Nine-day novena";
  const saintSlug = str(f.associatedSaintSlug);
  const saint = saintSlug ? humanizeSlug(saintSlug) : "";
  const start = str(f.typicalStartDate);
  const feastSlug = str(f.relatedFeastSlug);
  const feast = feastSlug
    ? humanizeSlug(feastSlug.replace(/^(solemnity|feast|memorial|optional-memorial)-/, ""))
    : "";
  const theme = str(f.intentionTheme);
  const to = saint ? ` to ${saint}` : "";
  if (start) return `${head}${to} · begins ${start}`;
  if (feast) return `${head}${to} · before ${feast}`;
  if (saint) return `${head}${to}`;
  return theme ? `${head} for ${theme}` : "A nine-day Catholic devotion";
}

